    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Фолклор и професионално творчество“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **фолклорна традиция и авторско композиторско творчество**, **фолклорни интонации в професионалната музика**.\n- **Основни знания и ориентири:** Обяснява взаимоотношенията между устната фолклорна традиция и авторското професионално композиторско творчество.\n- **Художествен анализ и специфика:** Посочва примери за вплитане на фолклорни интонации и метроритми в класическата, джазовата и популярната музика.\n- **Практическо и творческо приложение:** Разграничава автентичния фолклор от фолклороподобните практики на съвременната музикална сцена.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Фолклор и професионално творчество“: 1) Разпознаване и дефиниране на ключовите понятия (фолклорна традиция и авторско композиторско творчество; фолклорни интонации в професионалната музика); 2) Стилистичен и технологичен анализ (Посочва примери за вплитане на фолклорни интонации и метроритми в класическата, джазовата и популярната музика.); 3) Творческо приложение и аргументирана оценка (Разграничава автентичния фолклор от фолклороподобните практики на съвременната музикална сцена.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Фолклор и професионално творчество“.",
