    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Български национален стил“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **български национален музикален стил**, **поколения български композитори**.\n- **Основни знания и ориентири:** Анализира формирането и стилистичните особености на българския национален музикален стил в творчеството на първото и второто поколение български композитори.\n- **Художествен анализ и специфика:** Разпознава характерните метроритмични, ладови и темброви белези на българската художествена музика.\n- **Практическо и творческо приложение:** Разграничава по стилов признак творби от български и чуждестранни композитори.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Български национален стил“: 1) Разпознаване и дефиниране на ключовите понятия (български национален музикален стил; поколения български композитори); 2) Стилистичен и технологичен анализ (Разпознава характерните метроритмични, ладови и темброви белези на българската художествена музика.); 3) Творческо приложение и аргументирана оценка (Разграничава по стилов признак творби от български и чуждестранни композитори.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Български национален стил“.",
