    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Формообразуващи принципи“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **формообразуващи принципи: повторност, вариантност и контраст**, **музикална тема, мотив, фраза и период**.\n- **Основни знания и ориентири:** Познава основните формообразуващи принципи в музиката: повторност (буквална и репризна), вариантност (вариране) и контраст.\n- **Художествен анализ и специфика:** Разграничава структурните елементи на музикалната реч: мотив, фраза, полуизречение и период (музикална тема).\n- **Практическо и творческо приложение:** Проследява действието на формообразуващите принципи при слухов анализ на музикални творби.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Формообразуващи принципи“: 1) Разпознаване и дефиниране на ключовите понятия (формообразуващи принципи: повторност, вариантност и контраст; музикална тема, мотив, фраза и период); 2) Стилистичен и технологичен анализ (Разграничава структурните елементи на музикалната реч: мотив, фраза, полуизречение и период (музикална тема).); 3) Творческо приложение и аргументирана оценка (Проследява действието на формообразуващите принципи при слухов анализ на музикални творби.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Формообразуващи принципи“.",
