    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Прости песенни и инструментални форми“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **проста едноделна, двуделна и триделна форма**, **репризност в простите музикални форми**.\n- **Основни знания и ориентири:** Познава строежа и схемите на простите музикални форми: проста едноделна, проста двуделна (безрепризна и репризна) и проста триделна форма.\n- **Художествен анализ и специфика:** Разпознава простите песенни и инструментални форми в народни песни, популярни песни и класически инструментални миниатюри.\n- **Практическо и творческо приложение:** Определя границите между дяловете в простите форми по слух и по нотен текст.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Прости песенни и инструментални форми“: 1) Разпознаване и дефиниране на ключовите понятия (проста едноделна, двуделна и триделна форма; репризност в простите музикални форми); 2) Стилистичен и технологичен анализ (Разпознава простите песенни и инструментални форми в народни песни, популярни песни и класически инструментални миниатюри.); 3) Творческо приложение и аргументирана оценка (Определя границите между дяловете в простите форми по слух и по нотен текст.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Прости песенни и инструментални форми“.",
