    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Рондо – форма. Вариационна форма“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **форма рондо (рефрен и епизоди)**, **вариационна форма (тема с вариации)**.\n- **Основни знания и ориентири:** Обяснява структурата на формата рондо (редуване на основна тема – рефрен с контрастни епизоди) и на вариационната форма (тема с вариации).\n- **Художествен анализ и специфика:** Разпознава и проследява рондообразното и вариационното развитие във вокални и инструментални произведения.\n- **Практическо и творческо приложение:** Съпоставя класически и фолклорни образци на вариационно изграждане.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Рондо – форма. Вариационна форма“: 1) Разпознаване и дефиниране на ключовите понятия (форма рондо (рефрен и епизоди); вариационна форма (тема с вариации)); 2) Стилистичен и технологичен анализ (Разпознава и проследява рондообразното и вариационното развитие във вокални и инструментални произведения.); 3) Творческо приложение и аргументирана оценка (Съпоставя класически и фолклорни образци на вариационно изграждане.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Рондо – форма. Вариационна форма“.",
