    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Сонатно-симфоничен цикъл. Соната и симфония“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **сонатно-симфоничен цикъл**, **жанрове соната и симфония**.\n- **Основни знания и ориентири:** Познава четиричастната структура, темповия и образния профил на класическия сонатно-симфоничен цикъл.\n- **Художествен анализ и специфика:** Анализира характера и музикалните форми на отделните части в жанровете соната и симфония.\n- **Практическо и творческо приложение:** Проследява съотношението на частите в образци от творчеството на Хайдн, Моцарт, Бетовен и романтиците.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Сонатно-симфоничен цикъл. Соната и симфония“: 1) Разпознаване и дефиниране на ключовите понятия (сонатно-симфоничен цикъл; жанрове соната и симфония); 2) Стилистичен и технологичен анализ (Анализира характера и музикалните форми на отделните части в жанровете соната и симфония.); 3) Творческо приложение и аргументирана оценка (Проследява съотношението на частите в образци от творчеството на Хайдн, Моцарт, Бетовен и романтиците.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Сонатно-симфоничен цикъл. Соната и симфония“.",
