    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Инструментални и камерно-инструментални жанрове“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **инструментална и клавирна миниатюра**, **камерни ансамбли: дует, трио, квартет и квинтет**.\n- **Основни знания и ориентири:** Характеризира жанровете на соловата и камерно-инструменталната музика: прелюд, етюд, ноктюрно, експромт, клавирна миниатюра и камерни ансамбли (дует, трио, струнен квартет, квинтет).\n- **Художествен анализ и специфика:** Разграничава програмната от непрограмната (абсолютната) инструментална музика и жанровете симфонична поема и сюита.\n- **Практическо и творческо приложение:** Анализира жанрови особености в инструменталната музика от различни епохи.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Инструментални и камерно-инструментални жанрове“: 1) Разпознаване и дефиниране на ключовите понятия (инструментална и клавирна миниатюра; камерни ансамбли: дует, трио, квартет и квинтет); 2) Стилистичен и технологичен анализ (Разграничава програмната от непрограмната (абсолютната) инструментална музика и жанровете симфонична поема и сюита.); 3) Творческо приложение и аргументирана оценка (Анализира жанрови особености в инструменталната музика от различни епохи.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Инструментални и камерно-инструментални жанрове“.",
