    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Инструментален концерт“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **инструментален концерт и кончерто гросо**, **виртуозна солова каденца**.\n- **Основни знания и ориентири:** Познава тричастния строеж и жанровите особености на класическия инструментален концерт (съревнование и диалог между солиращ инструмент и симфоничен оркестър) и ролята на виртуозната солова каденца.\n- **Художествен анализ и специфика:** Сравнява бароковия жанр кончерто гросо с класическия и романтичния солов концерт.\n- **Практическо и творческо приложение:** Ориентира се в жанровите особености на съвременни инструментални концерти.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Инструментален концерт“: 1) Разпознаване и дефиниране на ключовите понятия (инструментален концерт и кончерто гросо; виртуозна солова каденца); 2) Стилистичен и технологичен анализ (Сравнява бароковия жанр кончерто гросо с класическия и романтичния солов концерт.); 3) Творческо приложение и аргументирана оценка (Ориентира се в жанровите особености на съвременни инструментални концерти.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Инструментален концерт“.",
