    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Вокално-инструментални жанрове“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **кантатно-ораториални жанрове: оратория, кантата и пасион**, **духовни жанрове: меса, реквием и литургия; мадригал**.\n- **Основни знания и ориентири:** Характеризира големите вокално-инструментални жанрове: меса (и реквием), литургия, оратория, кантата и пасион, както и ренесансовия вокален жанр мадригал.\n- **Художествен анализ и специфика:** Познава основните части на месата и ролята на хора, солистите и оркестъра в ораторията и кантатата.\n- **Практическо и творческо приложение:** Съпоставя духовни и светски образци на кантатно-ораториалния жанр.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Вокално-инструментални жанрове“: 1) Разпознаване и дефиниране на ключовите понятия (кантатно-ораториални жанрове: оратория, кантата и пасион; духовни жанрове: меса, реквием и литургия; мадригал); 2) Стилистичен и технологичен анализ (Познава основните части на месата и ролята на хора, солистите и оркестъра в ораторията и кантатата.); 3) Творческо приложение и аргументирана оценка (Съпоставя духовни и светски образци на кантатно-ораториалния жанр.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Вокално-инструментални жанрове“.",
