    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музиката в киното, театъра и телевизията“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **театрална и филмова музика (саундтрак)**, **музика във видеоклипа, рекламата и шоуспектакъла**.\n- **Основни знания и ориентири:** Обяснява приложните и драматургичните функции на музиката в театъра, киното и телевизията.\n- **Художествен анализ и специфика:** Познава спецификата на филмовата музика (саундтрак, лайтмотивна система, фонова и вътрешнокадрова музика) и музиката в рекламата, видеоклипа и шоуспектакъла.\n- **Практическо и творческо приложение:** Коментира творчеството на световноизвестни и български композитори на филмова и театрална музика.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музиката в киното, театъра и телевизията“: 1) Разпознаване и дефиниране на ключовите понятия (театрална и филмова музика (саундтрак); музика във видеоклипа, рекламата и шоуспектакъла); 2) Стилистичен и технологичен анализ (Познава спецификата на филмовата музика (саундтрак, лайтмотивна система, фонова и вътрешнокадрова музика) и музиката в рекламата, видеоклипа и шоуспектакъла.); 3) Творческо приложение и аргументирана оценка (Коментира творчеството на световноизвестни и български композитори на филмова и театрална музика.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музиката в киното, театъра и телевизията“.",
