    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музика и медии“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **музика в електронните медии и дигиталните платформи**, **авторско право и музикална журналистика**.\n- **Основни знания и ориентири:** Познава спецификата на разпространение и потребление на музика чрез електронните медии, радиото, телевизията и интернет стрийминг платформите.\n- **Художествен анализ и специфика:** Дискутира влиянието на дигиталните медии върху формирането на музикалния вкус и защитата на авторските права.\n- **Практическо и творческо приложение:** Използва дигитални източници за проучване и представяне на музикална информация.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музика и медии“: 1) Разпознаване и дефиниране на ключовите понятия (музика в електронните медии и дигиталните платформи; авторско право и музикална журналистика); 2) Стилистичен и технологичен анализ (Дискутира влиянието на дигиталните медии върху формирането на музикалния вкус и защитата на авторските права.); 3) Творческо приложение и аргументирана оценка (Използва дигитални източници за проучване и представяне на музикална информация.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музика и медии“.",
