    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Българската популярна музика през ХХ и ХХІ век“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **българска популярна, рок и джаз музика**, **емблематични български поп изпълнители и рок групи**.\n- **Основни знания и ориентири:** Проследява възникването и основните етапи в развитието на българската популярна (забавна и естрадна), рок и джаз музика през XX и XXI век.\n- **Художествен анализ и специфика:** Посочва емблематични български композитори, поп изпълнители, рок групи и джаз музиканти.\n- **Практическо и творческо приложение:** Коментира критично и аргументирано масовите явления и стилови тенденции (вкл. попфолка) в съвременната музикална среда.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Българската популярна музика през ХХ и ХХІ век“: 1) Разпознаване и дефиниране на ключовите понятия (българска популярна, рок и джаз музика; емблематични български поп изпълнители и рок групи); 2) Стилистичен и технологичен анализ (Посочва емблематични български композитори, поп изпълнители, рок групи и джаз музиканти.); 3) Творческо приложение и аргументирана оценка (Коментира критично и аргументирано масовите явления и стилови тенденции (вкл. попфолка) в съвременната музикална среда.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Българската популярна музика през ХХ и ХХІ век“.",
