    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Български музикален фолклор“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **автентичен (изворен) български фолклор**, **обработен фолклор и фолклорни музикални диалекти**.\n- **Основни знания и ориентири:** Характеризира ладовите, метроритмичните, диалектните и инструменталните особености на българския музикален фолклор по фолклорни области.\n- **Художествен анализ и специфика:** Разграничава и анализира образци на автентичен (изворен) фолклор и обработен (аранжиран за народен хор и оркестър) фолклор.\n- **Практическо и творческо приложение:** Оценява световната уникалност на българското народно многогласие и неравноделните метруми.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Български музикален фолклор“: 1) Разпознаване и дефиниране на ключовите понятия (автентичен (изворен) български фолклор; обработен фолклор и фолклорни музикални диалекти); 2) Стилистичен и технологичен анализ (Разграничава и анализира образци на автентичен (изворен) фолклор и обработен (аранжиран за народен хор и оркестър) фолклор.); 3) Творческо приложение и аргументирана оценка (Оценява световната уникалност на българското народно многогласие и неравноделните метруми.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Български музикален фолклор“.",
