    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Етапи в развитието на българската музикална култура“** от **ПП: Музика — Модул 1. Музикална култура** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **етапи в развитието на българската музикална култура**, **класици на българската композиторска школа**.\n- **Основни знания и ориентири:** Проследява историческите етапи в развитието на българската музикална култура от Средновековието (Йоан Кукузел) и Възраждането до професионалното композиторско творчество след Освобождението.\n- **Художествен анализ и специфика:** Назовава класиците на българската композиторска школа (Емануил Манолов, Добри Христов, Панайот Пипков, Панчо Владигеров, Петко Стайнов, Любомир Пипков, Марин Големинов) и техни знакови творби.\n- **Практическо и творческо приложение:** Познава развитието на съвременната българска музикална култура и музикални институции.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Етапи в развитието на българската музикална култура“: 1) Разпознаване и дефиниране на ключовите понятия (етапи в развитието на българската музикална култура; класици на българската композиторска школа); 2) Стилистичен и технологичен анализ (Назовава класиците на българската композиторска школа (Емануил Манолов, Добри Христов, Панайот Пипков, Панчо Владигеров, Петко Стайнов, Любомир Пипков, Марин Големинов) и техни знакови творби.); 3) Творческо приложение и аргументирана оценка (Познава развитието на съвременната българска музикална култура и музикални институции.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Етапи в развитието на българската музикална култура“.",
