    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Звук – видове звуци“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **звукови вълни, звуков спектър и обертонове**, **качества на тона: височина, сила, трайност и тембър**.\n- **Основни знания и ориентири:** Обяснява физичната природа на звука (звукови вълни, честота, амплитуда, звуков спектър и натурален обертонов ред).\n- **Художествен анализ и специфика:** Разграничава музикален тон и шум и четирите основни качества на музикалния тон: височина, трайност, сила и тембър.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Звук – видове звуци“: 1) Разпознаване и дефиниране на ключовите понятия (звукови вълни, звуков спектър и обертонове; качества на тона: височина, сила, трайност и тембър); 2) Стилистичен и технологичен анализ (Разграничава музикален тон и шум и четирите основни качества на музикалния тон: височина, трайност, сила и тембър.); 3) Творческо приложение и аргументирана оценка (Разграничава музикален тон и шум и четирите основни качества на музикалния тон: височина, трайност, сила и тембър.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Звук – видове звуци“.",
