    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музикална система. Строй“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **музикална система, звукоред и темпериран строй**, **полутон, цял тон и енхармонизъм**.\n- **Основни знания и ориентири:** Дефинира понятията музикална система, звукоред и музикален строй (чист и равномерно темпериран строй).\n- **Художествен анализ и специфика:** Обяснява делението на октавата на дванадесет равни полутона в темперирания строй и явлението енхармонизъм.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музикална система. Строй“: 1) Разпознаване и дефиниране на ключовите понятия (музикална система, звукоред и темпериран строй; полутон, цял тон и енхармонизъм); 2) Стилистичен и технологичен анализ (Обяснява делението на октавата на дванадесет равни полутона в темперирания строй и явлението енхармонизъм.); 3) Творческо приложение и аргументирана оценка (Обяснява делението на октавата на дванадесет равни полутона в темперирания строй и явлението енхармонизъм.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музикална система. Строй“.",
