    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музикална писменост“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **октавови групи, нотни ключове и знаци за алтерация**, **знаци за октавово пренасяне, динамични знаци и абревиатури**.\n- **Основни знания и ориентири:** Познава октавовите групи в музикалния звукоред, словесните и буквените означения на тоновете и нотните ключове (сол и фа).\n- **Художествен анализ и специфика:** Прилага знаците за алтерация, знаците за октавово пренасяне, динамичните означения и абревиатурите за съкратено записване на нотен текст.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музикална писменост“: 1) Разпознаване и дефиниране на ключовите понятия (октавови групи, нотни ключове и знаци за алтерация; знаци за октавово пренасяне, динамични знаци и абревиатури); 2) Стилистичен и технологичен анализ (Прилага знаците за алтерация, знаците за октавово пренасяне, динамичните означения и абревиатурите за съкратено записване на нотен текст.); 3) Творческо приложение и аргументирана оценка (Прилага знаците за алтерация, знаците за октавово пренасяне, динамичните означения и абревиатурите за съкратено записване на нотен текст.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музикална писменост“.",
