    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Акорди“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **тризвучие (квинтакорд) и обръщения: секстакорд и квартсекстакорд**, **септакорд и обръщения: квинтсекстакорд, терцквартакорд и секундакорд**.\n- **Основни знания и ориентири:** Обяснява терцовия принцип за строеж на класическите акорди: четирите вида тризвучия (мажорно, минорно, умалено и увеличено) и техните обръщения (секстакорд и квартсекстакорд).\n- **Художествен анализ и специфика:** Познава строежа на мажорно-малкия (доминантов) септакорд и трите му обръщения: квинтсекстакорд, терцквартакорд и секундакорд.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Акорди“: 1) Разпознаване и дефиниране на ключовите понятия (тризвучие (квинтакорд) и обръщения: секстакорд и квартсекстакорд; септакорд и обръщения: квинтсекстакорд, терцквартакорд и секундакорд); 2) Стилистичен и технологичен анализ (Познава строежа на мажорно-малкия (доминантов) септакорд и трите му обръщения: квинтсекстакорд, терцквартакорд и секундакорд.); 3) Творческо приложение и аргументирана оценка (Познава строежа на мажорно-малкия (доминантов) септакорд и трите му обръщения: квинтсекстакорд, терцквартакорд и секундакорд.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Акорди“.",
