    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Ладов усет“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **ладов усет и интониране в мажор и минор**, **разновидности на мажора и минора (натурален, хармоничен, мелодичен, бихармоничен)**.\n- **Основни знания и ориентири:** Разпознава по слух и интонира чисто мелодии и звукореди в натурален, хармоничен, мелодичен и бихармоничен мажор и минор.\n- **Художествен анализ и специфика:** Определя по слух ладовата принадлежност на художествени и фолклорни музикални примери.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Ладов усет“: 1) Разпознаване и дефиниране на ключовите понятия (ладов усет и интониране в мажор и минор; разновидности на мажора и минора (натурален, хармоничен, мелодичен, бихармоничен)); 2) Стилистичен и технологичен анализ (Определя по слух ладовата принадлежност на художествени и фолклорни музикални примери.); 3) Творческо приложение и аргументирана оценка (Определя по слух ладовата принадлежност на художествени и фолклорни музикални примери.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Ладов усет“.",
