    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Усет за многогласие“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **усет за многогласие и хармоничен слух**, **традиционен български двуглас и акордови обръщения**.\n- **Основни знания и ориентири:** Разпознава по слух вида на многогласието (хомофонно, полифонично, бурдонно) и диалектните особености на традиционния български двуглас.\n- **Художествен анализ и специфика:** Възприема диференцирано и интонира тоновете на мажорни и минорни тризвучия и техните обръщения и проследява гласовете в двугласни примери.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Усет за многогласие“: 1) Разпознаване и дефиниране на ключовите понятия (усет за многогласие и хармоничен слух; традиционен български двуглас и акордови обръщения); 2) Стилистичен и технологичен анализ (Възприема диференцирано и интонира тоновете на мажорни и минорни тризвучия и техните обръщения и проследява гласовете в двугласни примери.); 3) Творческо приложение и аргументирана оценка (Възприема диференцирано и интонира тоновете на мажорни и минорни тризвучия и техните обръщения и проследява гласовете в двугласни примери.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Усет за многогласие“.",
