    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Пеене по ноти“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **солфежиране (пеене по ноти от пръв поглед)**, **интонационна чистота и тактуване**.\n- **Основни знания и ориентири:** Притежава нотно-четивни умения за солфежиране на непознат нотен текст със средна трудност с диригентски жест.\n- **Художествен анализ и специфика:** Пее по ноти конструктивни и художествени музикални примери в тоналности до два арматурни знака в равноделни и неравноделни размери.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Пеене по ноти“: 1) Разпознаване и дефиниране на ключовите понятия (солфежиране (пеене по ноти от пръв поглед); интонационна чистота и тактуване); 2) Стилистичен и технологичен анализ (Пее по ноти конструктивни и художествени музикални примери в тоналности до два арматурни знака в равноделни и неравноделни размери.); 3) Творческо приложение и аргументирана оценка (Пее по ноти конструктивни и художествени музикални примери в тоналности до два арматурни знака в равноделни и неравноделни размери.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Пеене по ноти“.",
