    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Слухов анализ“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **слухов анализ на интервали, акорди и звукореди**, **функционален слухов анализ**.\n- **Основни знания и ориентири:** Анализира по слух прости мелодични и хармонични интервали, мажорни и минорни тризвучия с обръщенията им и доминантов септакорд с обръщенията му.\n- **Художествен анализ и специфика:** Разпознава по слух мажорни и минорни звукореди в натурален, хармоничен, мелодичен и бихармоничен вид.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Слухов анализ“: 1) Разпознаване и дефиниране на ключовите понятия (слухов анализ на интервали, акорди и звукореди; функционален слухов анализ); 2) Стилистичен и технологичен анализ (Разпознава по слух мажорни и минорни звукореди в натурален, хармоничен, мелодичен и бихармоничен вид.); 3) Творческо приложение и аргументирана оценка (Разпознава по слух мажорни и минорни звукореди в натурален, хармоничен, мелодичен и бихармоничен вид.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Слухов анализ“.",
