    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музикална диктовка“** от **ПП: Музика — Модул 2. Теория на музиката** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **едногласна музикална диктовка**, **нотен запис по слух на мелодия и ритъм**.\n- **Основни знания и ориентири:** Записва точно с ноти едногласни конструктивни и художествени мелодични примери (музикална диктовка) в тоналности до един знак и в равноделни размери.\n- **Художествен анализ и специфика:** Определя тоналността, размера, ритмичните групи и случайните алтерации в прослушаната музикална фраза.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музикална диктовка“: 1) Разпознаване и дефиниране на ключовите понятия (едногласна музикална диктовка; нотен запис по слух на мелодия и ритъм); 2) Стилистичен и технологичен анализ (Определя тоналността, размера, ритмичните групи и случайните алтерации в прослушаната музикална фраза.); 3) Творческо приложение и аргументирана оценка (Определя тоналността, размера, ритмичните групи и случайните алтерации в прослушаната музикална фраза.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музикална диктовка“.",
