    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Запознаване с музикалния инструмент/глас“** от **ПП: Музика — Модул 3. Музикален инструмент/пеене** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **инструментални и вокални изпълнителски школи**, **устройство на инструмента / певчески резонатори и регистри**.\n- **Основни знания и ориентири:** Познава историята, устройството, акустичните особености и техническите възможности на изучавания музикален инструмент или певческия глас.\n- **Художествен анализ и специфика:** Познава основните инструментални и вокални изпълнителски школи и практики (солова, камерна, оркестрова и хорова).\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Запознаване с музикалния инструмент/глас“: 1) Разпознаване и дефиниране на ключовите понятия (инструментални и вокални изпълнителски школи; устройство на инструмента / певчески резонатори и регистри); 2) Стилистичен и технологичен анализ (Познава основните инструментални и вокални изпълнителски школи и практики (солова, камерна, оркестрова и хорова).); 3) Творческо приложение и аргументирана оценка (Познава основните инструментални и вокални изпълнителски школи и практики (солова, камерна, оркестрова и хорова).).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Запознаване с музикалния инструмент/глас“.",
