    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Свирене на музикален инструмент/пеене“** от **ПП: Музика — Модул 3. Музикален инструмент/пеене** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **изпълнителски репертоар и ансамблово музициране**, **класова продукция и сценично поведение**.\n- **Основни знания и ориентири:** Изпълнява по ноти и по слух музикални произведения от учебния репертоар и от класическата, фолклорната, поп-рок и джаз музиката.\n- **Художествен анализ и специфика:** Участва активно в солови и ансамблови форми на музициране и класови продукции.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Свирене на музикален инструмент/пеене“: 1) Разпознаване и дефиниране на ключовите понятия (изпълнителски репертоар и ансамблово музициране; класова продукция и сценично поведение); 2) Стилистичен и технологичен анализ (Участва активно в солови и ансамблови форми на музициране и класови продукции.); 3) Творческо приложение и аргументирана оценка (Участва активно в солови и ансамблови форми на музициране и класови продукции.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Свирене на музикален инструмент/пеене“.",
