    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Базови изпълнителски умения“** от **ПП: Музика — Модул 3. Музикален инструмент/пеене** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **постановка на свирене/пеене и звукоизвличане (вокалообразуване)**, **певческа опора, артикулация (щрихи) и музикално фразиране**.\n- **Основни знания и ориентири:** Овладява правилна постановка на свирене или пеене (певческо дишане и опора), чисто звукоизвличане, интонация и инструментална/вокална артикулация (щрихи).\n- **Художествен анализ и специфика:** Осъществява изразително фразиране с подходящи динамични и темпови нюанси.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Базови изпълнителски умения“: 1) Разпознаване и дефиниране на ключовите понятия (постановка на свирене/пеене и звукоизвличане (вокалообразуване); певческа опора, артикулация (щрихи) и музикално фразиране); 2) Стилистичен и технологичен анализ (Осъществява изразително фразиране с подходящи динамични и темпови нюанси.); 3) Творческо приложение и аргументирана оценка (Осъществява изразително фразиране с подходящи динамични и темпови нюанси.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Базови изпълнителски умения“.",
