    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Художествена интерпретация“** от **ПП: Музика — Модул 3. Музикален инструмент/пеене** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **художествена интерпретация и изпълнителски стил**, **италианска терминология за темпо, динамика и характер**.\n- **Основни знания и ориентири:** Изгражда собствена художествена интерпретация на изпълняваното произведение, съобразена със стиловите особености на епохата и композитора.\n- **Художествен анализ и специфика:** Познава и спазва италианската музикална терминология за темпо, динамика, агогика и характер.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Художествена интерпретация“: 1) Разпознаване и дефиниране на ключовите понятия (художествена интерпретация и изпълнителски стил; италианска терминология за темпо, динамика и характер); 2) Стилистичен и технологичен анализ (Познава и спазва италианската музикална терминология за темпо, динамика, агогика и характер.); 3) Творческо приложение и аргументирана оценка (Познава и спазва италианската музикална терминология за темпо, динамика, агогика и характер.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Художествена интерпретация“.",
