    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музикални практики“** от **ПП: Музика — Модул 3. Музикален инструмент/пеене** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **публично концертно изпълнение и сценична култура**, **транспониране по слух и по ноти**.\n- **Основни знания и ориентири:** Прилага знанията си за музикалните жанрове и стилове в публичната изпълнителска практика и овладява сценичното вълнение.\n- **Художествен анализ и специфика:** Транспонира по слух и по ноти познати мелодии в тоналности до един арматурен знак.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музикални практики“: 1) Разпознаване и дефиниране на ключовите понятия (публично концертно изпълнение и сценична култура; транспониране по слух и по ноти); 2) Стилистичен и технологичен анализ (Транспонира по слух и по ноти познати мелодии в тоналности до един арматурен знак.); 3) Творческо приложение и аргументирана оценка (Транспонира по слух и по ноти познати мелодии в тоналности до един арматурен знак.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музикални практики“.",
