    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музикален анализ на изпълнявания репертоар“** от **ПП: Музика — Модул 3. Музикален инструмент/пеене** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **слухов контрол и самоконтрол при музициране**, **изпълнителски и формален анализ на партитурата**.\n- **Основни знания и ориентири:** Осъществява слухов самоконтрол и критичен анализ на собствените и чуждите инструментални или вокални изпълнения.\n- **Художествен анализ и специфика:** Определя музикалната форма, жанра и ролята на музикалноизразните средства в произведенията от изучавания репертоар.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музикален анализ на изпълнявания репертоар“: 1) Разпознаване и дефиниране на ключовите понятия (слухов контрол и самоконтрол при музициране; изпълнителски и формален анализ на партитурата); 2) Стилистичен и технологичен анализ (Определя музикалната форма, жанра и ролята на музикалноизразните средства в произведенията от изучавания репертоар.); 3) Творческо приложение и аргументирана оценка (Определя музикалната форма, жанра и ролята на музикалноизразните средства в произведенията от изучавания репертоар.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музикален анализ на изпълнявания репертоар“.",
