    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Запознаване с пианото/електронните инструменти“** от **ПП: Музика — Модул 4. Пиано/електронни инструменти** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **акустично пиано, синтезатор и музикален софтуер (секвенсер)**, **MIDI протокол и цифров семплер**.\n- **Основни знания и ориентири:** Познава историята, устройството и техническите възможности на акустичното пиано и съвременните електронни клавишни инструменти (синтезатори, MIDI контролери и музикален софтуер – секвенсери).\n- **Художествен анализ и специфика:** Познава приноса и традициите на българската клавирна школа.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Запознаване с пианото/електронните инструменти“: 1) Разпознаване и дефиниране на ключовите понятия (акустично пиано, синтезатор и музикален софтуер (секвенсер); MIDI протокол и цифров семплер); 2) Стилистичен и технологичен анализ (Познава приноса и традициите на българската клавирна школа.); 3) Творческо приложение и аргументирана оценка (Познава приноса и традициите на българската клавирна школа.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Запознаване с пианото/електронните инструменти“.",
