    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Свирене на пиано/електронни инструменти“** от **ПП: Музика — Модул 4. Пиано/електронни инструменти** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **свирене по партитура и буквено-цифрови акордови означения**, **аранжимент и режим на автоматичен акомпанимент**.\n- **Основни знания и ориентири:** Изпълнява по ноти и по слух клавирни пиеси и мелодии с акомпанимент по партитура и буквено-цифрови означения на акордите.\n- **Художествен анализ и специфика:** Използва тембровите, ритмичните и аранжиращите функции на електронните клавишни инструменти в солова и ансамблова практика.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Свирене на пиано/електронни инструменти“: 1) Разпознаване и дефиниране на ключовите понятия (свирене по партитура и буквено-цифрови акордови означения; аранжимент и режим на автоматичен акомпанимент); 2) Стилистичен и технологичен анализ (Използва тембровите, ритмичните и аранжиращите функции на електронните клавишни инструменти в солова и ансамблова практика.); 3) Творческо приложение и аргументирана оценка (Използва тембровите, ритмичните и аранжиращите функции на електронните клавишни инструменти в солова и ансамблова практика.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Свирене на пиано/електронни инструменти“.",
