    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Базови изпълнителски умения“** от **ПП: Музика — Модул 4. Пиано/електронни инструменти** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **клавирна постановка, пръстовка (апликатура) и педализация**, **семплиране и работа с MIDI файлове**.\n- **Основни знания и ориентири:** Овладява правилна клавирна постановка, пръстовка (апликатура), координация между лява и дясна ръка, артикулационни щрихи и педализация при пианото.\n- **Художествен анализ и специфика:** Настройва контролните панели и функциите на електронните инструменти и работи с MIDI файлове и семплиране.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Базови изпълнителски умения“: 1) Разпознаване и дефиниране на ключовите понятия (клавирна постановка, пръстовка (апликатура) и педализация; семплиране и работа с MIDI файлове); 2) Стилистичен и технологичен анализ (Настройва контролните панели и функциите на електронните инструменти и работи с MIDI файлове и семплиране.); 3) Творческо приложение и аргументирана оценка (Настройва контролните панели и функциите на електронните инструменти и работи с MIDI файлове и семплиране.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Базови изпълнителски умения“.",
