    "originalNoteExcerpt": "### 1. Теоретична основа и художествен контекст\nТемата **„Музикални практики“** от **ПП: Музика — Модул 4. Пиано/електронни инструменти** разглежда ключови закономерности от музикалното изкуство и култура по официалната учебна програма на МОН. Основните понятия в урока са: **дигитална музикална практика, синбек и кавър версия**, **транспониране на клавишен инструмент**.\n- **Основни знания и ориентири:** Участва в публични концертни изяви и дигитални музикални практики (създаване на кавър версии и синбек акомпанименти).\n- **Художествен анализ и специфика:** Транспонира на клавишен инструмент познати мелодии и акомпанименти в тоналности до един знак.\n### 2. Методологично правило и модел за анализ\n- **Златно правило:** При слухов и теоретичен анализ винаги свързвайте музикалноизразните средства (мелодия, метроритъм, лад, хармония, тембър, динамика) с формата, жанра и стиловите особености на историческата епоха.\n- **Алгоритъм за анализ на творба и задача:** Практически модел за „Музикални практики“: 1) Разпознаване и дефиниране на ключовите понятия (дигитална музикална практика, синбек и кавър версия; транспониране на клавишен инструмент); 2) Стилистичен и технологичен анализ (Транспонира на клавишен инструмент познати мелодии и акомпанименти в тоналности до един знак.); 3) Творческо приложение и аргументирана оценка (Транспонира на клавишен инструмент познати мелодии и акомпанименти в тоналности до един знак.).\n### 3. Често допускани грешки и капани на изпит\n- **Внимание:** Не смесвайте понятията музикална форма (структурна схема на творбата), музикален жанр (вид и предназначение на произведението) и музикален стил (белези на епохата, националната школа или автора) при въпроси върху „Музикални практики“.",
